  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- postpartum week 55: Eating well as your toddler starts daycare (CORRECTED — mother-centric rework)
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   55,
   NULL,
   'Phase 5 of 6 — Beyond the first year',
   'Eating well as your toddler starts daycare',
   '"A new routine doesn''t leave less room for your own meals — it just asks you to protect them differently."',
   'Starting daycare or preschool is a big routine shift — new drop-off and pickup windows, a toddler who may be more tired or clingy at home, and a schedule that takes weeks to settle. Your own regular meals can quietly get crowded out during that adjustment if you''re not deliberate about protecting them. Changes in childcare routines, and illnesses circulating at home, can disrupt your meals and rest. Keep simple food available, ask for practical help, and seek medical advice for persistent or severe symptoms. No single food or routine supplement is proven to prevent the ordinary run of daycare infections or make them disappear immediately. Handwashing, appropriate exclusion when ill and staying current with recommended vaccinations remain central. Food''s practical role is supporting adequate energy, protein and fluids — not acting as an instant "immunity booster." It''s reasonable for meals to get simpler during the adjustment weeks. A new routine is allowed to feel logistically harder before it feels easier, and that includes your own food, not just the household schedule.',
   'If you keep catching your toddler''s colds or stomach bugs: that''s common in the first year of group childcare and often eases in the second — food''s role is supporting adequate energy, protein and fluids while you''re unwell, not acting as an immunity booster. Use a condition-specific supplement only when your care team has clinically indicated it, not as a routine daycare precaution. If a chronic condition you manage tends to flare with disrupted sleep or new stress: a demanding transition like this one can be a trigger — mention any increase in symptoms to your care team rather than assuming it''s simply the cost of the adjustment. If you''re newly pregnant or still breastfeeding while managing this transition: regular meals matter especially now — try not to let a rushed morning turn into a skipped one, even on the days that feel most chaotic. However smoothly or roughly this transition is going, the adjustment varies between families — and feeding yourself properly through it isn''t one more task competing for your attention, it''s part of how you get through it.',
   'Meat, fish and eggs can all sit comfortably in a regular week''s meals here, rotated for variety. If you are pregnant or breastfeeding and eat fish, FDA/EPA guidance recommends two to three adult servings weekly from its "Best Choices" list — about 113 g per serving before cooking. Follow local advisories. This is an option for fish eaters, not a requirement to add fish.',
   'Choose either option, not both — these are alternatives, not two separate meals. Repeating a combination you already enjoyed earlier in the week is completely fine; you don''t need six different dishes to get through the week. If nothing here appeals or time is short, reheated dal, rice and curd is an option if it suits your dietary needs and any care plan you follow. The "if you''re still hungry" suggestions are suggestions, not limits — adjust everything to your own appetite. Portions below are adjustable starting points, not maximum allowances — scale to your own appetite, activity and any care plan you follow. A cup means a standard 240ml measuring cup. Unless a dish says otherwise: rice or another cooked grain eaten on its own is one level cup (about 150g); khichdi (grain and dal cooked together) is a heaped cup (about 250g total), of which dal makes up roughly a third; a dal, bean or lentil curry eaten as its own dish is three-quarters of a cup cooked (about 150g); a roti or paratha is one medium piece, and toast is 2 slices. In a mixed rice or grain dish, the meat, fish, paneer or legume component is about 75-100g of that ingredient (roughly a palm-sized piece, or half a cup of cooked legumes), counted separately from the grain itself. Paneer, tofu, meat or fish eaten as a dish''s main item is 75-100g cooked (a palm-sized piece), or two eggs — these are different foods with different protein, iron and fat content, and are not nutritionally interchangeable just because they share a similar portion size. Curd or milk is a small bowl or glass (150-200ml); a cooked vegetable side is about a cup; nuts or seeds used as a topping are about a tablespoon (roughly 10-15g). The meals contribute different nutrients across the day; each individual meal or snack does not need to include every food group. Choose varied meals through the day and include a dependable protein source and a dependable calcium source at more than one meal — curd, milk or paneer — rather than relying on trace amounts in mixed dishes or an optional extra. If you avoid dairy, include measured portions of calcium-fortified alternatives or calcium-set tofu, checking the label. Ragi and sesame can contribute, but should not be treated as equivalent replacements without checking quantities. Adults generally need about 1,000 mg of calcium a day, including while breastfeeding — a single measured serving is a helpful building block, not the whole day''s requirement on its own. Iron, vitamin B12, iodine and vitamin D are worth particular attention across a full week, especially if you follow a restricted diet. Food choices alone don''t rule out a need for supplementation — ask your own clinician what''s right for you.',
   '[{"day_number": 1, "title": "Anchor", "notes": "A new daycare or preschool routine can reshuffle everything — mornings, moods, energy, appetite. It''s allowed to feel like an adjustment for weeks, and your own meals don''t have to wait until things settle down to matter.", "breakfast_a": "Vegetable poha (1 cup) with peanuts (15g) and a small bowl of curd (150g)", "breakfast_b": "Egg-and-tomato omelette (2 eggs) with toast (2 slices) and a glass of milk (200ml)", "lunch_a": "Rice (1 cup cooked) with a toor-moong dal (3/4 cup) and a cooked vegetable", "lunch_b": "Chicken curry (100g chicken) with rice (1 cup cooked) and a leafy green vegetable", "nourishment_break_a": "Seasonal fruit with roasted almonds (15g) and a small bowl of curd (150g)", "nourishment_break_b": "Buttermilk (200ml) with roasted cumin and roasted chana (30g)", "dinner_a": "Roti (2 pieces) with a masoor-moong dal (3/4 cup) and a cooked vegetable", "dinner_b": "Fish curry (100g fish) with roti (2 pieces) and a leafy green vegetable", "still_hungry": "A boiled egg"}, {"day_number": 2, "title": "The first few weeks of drop-off", "notes": "Early mornings can get tighter once drop-off enters the picture, and it''s easy to let your own breakfast shrink to whatever''s fastest or skip it while managing a clingy toddler. A meal that takes five minutes still counts as a real one — it doesn''t need to be elaborate to matter.", "breakfast_a": "Vegetable-stuffed paratha (1 medium) with a small bowl of curd (150g)", "breakfast_b": "Boiled eggs (2) with a banana and a glass of milk (200ml)", "lunch_a": "Rice (1 cup cooked) with a chana curry (3/4 cup) and a sautéed vegetable", "lunch_b": "Egg-and-potato curry (2 eggs) with roti (2 pieces) and a cooked vegetable", "nourishment_break_a": "Roasted chana (30g) with an apple and a small bowl of curd (150g)", "nourishment_break_b": "Dates with a glass of milk (200ml)", "dinner_a": "Roti (2 pieces) with a rajma-vegetable curry (3/4 cup)", "dinner_b": "Mutton-and-onion curry (100g mutton) with rice (1 cup cooked) and a cooked vegetable", "still_hungry": "Plain crackers with curd (150g) or milk (200ml)"}, {"day_number": 3, "title": "When you catch what they bring home", "notes": "Changes in your child''s health and routine can ripple into your own meals and rest this week. Keep something simple on hand, ask for practical help where you can, and don''t wait to seek medical advice if symptoms are persistent or severe — for yourself or your child. Worth knowing: During vomiting or diarrhoea, take small frequent sips of fluids you can tolerate rather than a full glass at once. An oral rehydration solution (ORS) can help alongside food, not instead of it, when fluid losses are significant or your care team has advised it — prepare a packaged product exactly as directed. Sugary drinks and homemade \"immune\" mixtures aren''t substitutes for appropriate rehydration or medical care. Seek medical help if you cannot retain fluids or develop signs of significant dehydration.", "breakfast_a": "Vegetable dalia (1 cup) with a small bowl of curd (150g), if tolerated", "breakfast_b": "Fully cooked scrambled eggs (2 eggs) with toast (2 slices) and a glass of milk (200ml), if tolerated", "lunch_a": "Soft vegetable-moong dal khichdi (1 heaped cup) with ghee and a small bowl of curd (150g)", "lunch_b": "Chicken-and-vegetable soup (75g chicken) with rice (1 cup cooked)", "nourishment_break_a": "Toast (2 slices) with mashed banana and a small bowl of curd (150g), if tolerated", "nourishment_break_b": "A ripe banana with a glass of milk (200ml), if tolerated", "dinner_a": "Moong dal soup (3/4 cup) with rice (1 cup cooked) and a soft cooked vegetable, plus a small bowl of curd (150g)", "dinner_b": "Egg curry (2 eggs) with soft rice (1 cup cooked) and a soft cooked vegetable", "still_hungry": "A small bowl of curd or warm milk (150-200ml), if tolerated"}, {"day_number": 4, "title": "When the whole house is passing something back and forth", "notes": "Some stretches, it can feel like one cold hands off to the next before anyone fully recovers. No single food or supplement is proven to break that cycle faster — handwashing, keeping a sick child home when advised, and staying current on vaccinations remain central. Food''s practical role is supporting adequate energy, protein and fluids for whoever''s under the weather, not acting as an instant immunity booster. Worth knowing: For yourself: difficulty breathing, unusual drowsiness or reduced responsiveness, inability to keep fluids down, signs of dehydration, severe weakness, or rapidly worsening symptoms require urgent medical advice. For your toddler, follow their paediatrician''s guidance on fever and illness — check Child Care for more on recognising when a child needs urgent attention.", "breakfast_a": "Vegetable upma (1 cup) with roasted peanuts (15g) and a small bowl of curd (150g)", "breakfast_b": "Egg-and-spinach toast (2 eggs, 2 slices) with a glass of milk (200ml)", "lunch_a": "Rice (1 cup cooked) with a lauki-moong dal (3/4 cup) and a cooked vegetable", "lunch_b": "Chicken-and-vegetable curry (100g chicken) with rice (1 cup cooked)", "nourishment_break_a": "Guava with roasted walnuts (15g) and a small bowl of curd (150g)", "nourishment_break_b": "Curd (150g) with a spoon of ground roasted flaxseed", "dinner_a": "Roti (2 pieces) with a moong-methi dal (3/4 cup) and a sautéed vegetable", "dinner_b": "Fish curry (100g fish) with rice (1 cup cooked) and a leafy green vegetable", "still_hungry": "A glass of warm milk (200ml)"}, {"day_number": 5, "title": "New windows, new meals", "notes": "If your old meal timings no longer fit around a new drop-off-and-pickup schedule, the timings are allowed to move. Batch-cooking a dal or curry that reheats well, or keeping simple protein options on hand, can make it easier to eat properly even on the days that feel most rushed.", "breakfast_a": "Ragi porridge (1 cup, prepared with milk, 200ml) with roasted almonds (15g); jaggery optional", "breakfast_b": "Egg bhurji (2 eggs) with multigrain toast (2 slices) and a glass of milk (200ml)", "lunch_a": "Rice (1 cup cooked) with a chana-tomato masala (3/4 cup) and a cooked vegetable", "lunch_b": "Prawn-and-vegetable curry (100g prawns) with rice (1 cup cooked)", "nourishment_break_a": "Roasted makhana (15g) with a guava and a small bowl of curd (150g)", "nourishment_break_b": "Buttermilk (200ml) with roasted sesame seeds", "dinner_a": "Roti (2 pieces) with a matki-tomato curry (3/4 cup) and a cooked vegetable", "dinner_b": "Paneer-and-capsicum curry (75g paneer) with rice (1 cup cooked)", "still_hungry": "A banana"}, {"day_number": 6, "title": "If guilt shows up", "notes": "Guilt about leaving your toddler at daycare, or relief that you have a few hours back, can both show up in the same week — sometimes the same afternoon. Neither one needs to be resolved before you feed yourself properly; a hard morning doesn''t cancel your right to a real lunch.", "breakfast_a": "Moong dal cheela (2 pieces) with tomato chutney and a small bowl of curd (150g)", "breakfast_b": "Egg-and-onion bhurji (2 eggs) with toast (2 slices) and a glass of milk (200ml)", "lunch_a": "Rice (1 cup cooked) with a rajma curry (3/4 cup) and a leafy green vegetable", "lunch_b": "Mutton-and-vegetable curry (100g mutton) with roti (2 pieces)", "nourishment_break_a": "Dates with roasted peanuts (15g) and a small bowl of curd (150g)", "nourishment_break_b": "Curd (150g) with a spoon of soaked chia seeds", "dinner_a": "Roti (2 pieces) with a green-moong dal (3/4 cup) and a cooked vegetable", "dinner_b": "Chicken tikka (100g chicken) with roti (2 pieces) and a cooked vegetable", "still_hungry": "A small bowl of curd (150g)"}, {"day_number": 7, "title": "A repeat-favourites day", "notes": "No new recipes today. Day 1''s combination is repeated below as a ready option — or swap in whichever meals from earlier in the week worked best for you. No forced choices today. What''s one part of your own routine — a meal, a break, a habit — that''s gotten smaller since this transition started, and is there a simple way to give it a bit of room back?", "breakfast_a": "Vegetable poha (1 cup) with peanuts (15g) and a small bowl of curd (150g)", "breakfast_b": "Egg-and-tomato omelette (2 eggs) with toast (2 slices) and a glass of milk (200ml)", "lunch_a": "Rice (1 cup cooked) with a toor-moong dal (3/4 cup) and a cooked vegetable", "lunch_b": "Chicken curry (100g chicken) with rice (1 cup cooked) and a leafy green vegetable", "nourishment_break_a": "Seasonal fruit with roasted almonds (15g) and a small bowl of curd (150g)", "nourishment_break_b": "Buttermilk (200ml) with roasted cumin and roasted chana (30g)", "dinner_a": "Roti (2 pieces) with a masoor-moong dal (3/4 cup) and a cooked vegetable", "dinner_b": "Chicken curry (100g chicken) with roti (2 pieces) and a leafy green vegetable", "still_hungry": "A boiled egg"}]'::jsonb,
   'What would it look like to treat a rushed, imperfect week as reason to feed yourself more carefully, rather than less?',
   'Next week continues Phase 5 with another piece of life beyond the first year — still grounded in the same idea: a demanding season is exactly when regular, adequate meals matter most, not a time to let them slide.')
