  looking_ahead = excluded.looking_ahead;

-- postpartum week 56: Eating well when your toddler becomes a picky eater (CORRECTED — mother-centric rework)
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   56,
   NULL,
   'Phase 5 of 6 — Beyond the first year',
   'Eating well when your toddler becomes a picky eater',
   '"Your child''s plate doesn''t need to be resolved before your own meal is worth finishing."',
   'Somewhere between one and three years old, many toddlers become more selective about food than they were as babies. How long this particular phase lasts and how it plays out varies by child — but whatever its course, it has little to do with your cooking or your effort. This week keeps the focus on your own eating specifically: whatever is playing out at the table, it isn''t a problem for you to solve by skipping your own meal, restricting your own diet, or treating a hard mealtime as something to get through before you''re allowed to eat properly yourself.',
   'If you have any ongoing health condition that affects your own diet — thyroid, diabetes, anaemia, or otherwise: let your clinician''s specific guidance for you take priority over the general suggestions in this chart. If you''re newly pregnant or still breastfeeding while managing this stage: your own protein and energy needs haven''t shrunk because mealtimes have gotten harder — protect your plate the same way you would any other week. Difficult mealtimes can happen. Your own nourishment still deserves attention while you seek support for any persistent concerns — and feeding yourself properly through it isn''t a reward you earn after theirs goes smoothly.',
   'Meat, fish and eggs can all sit comfortably in a regular week''s meals here, rotated for variety. If you are pregnant or breastfeeding and eat fish, FDA/EPA guidance recommends two to three adult servings weekly from its "Best Choices" list — about 113 g per serving before cooking. Follow local advisories. This is an option for fish eaters, not a requirement to add fish.',
   'Choose either option, not both — these are alternatives, not two separate meals. Repeating a combination you already enjoyed is completely fine; you don''t need a new dish every day. If nothing here appeals or time is short, reheated dal, rice and curd is an option if it suits your dietary needs and any care plan you follow. Portions below are adjustable starting points, not maximum allowances — scale to your own appetite, activity and any care plan you follow. A cup means a standard 240ml measuring cup. Unless a dish says otherwise: rice or another cooked grain eaten on its own is one level cup (about 150g); a dal, bean or lentil curry eaten as its own dish is three-quarters of a cup cooked (about 150g); a roti or paratha is one medium piece; an idli is 2-3 pieces, a dosa, uttapam, chilla or cheela is 1-2 pieces, and toast is 2 slices. In a mixed rice or grain dish, the meat, fish, paneer or legume component is about 75-100g of that ingredient (roughly a palm-sized piece, or half a cup of cooked legumes), counted separately from the grain itself. Paneer, tofu, meat or fish eaten as a dish''s main item is 75-100g cooked (a palm-sized piece), or two eggs — these are different foods with different protein, iron and fat content, and are not nutritionally interchangeable just because they share a similar portion size. Curd or milk is a small bowl or glass (150-200ml); a cooked vegetable side is about a cup; nuts or seeds used as a topping are about a tablespoon (roughly 10g). The meals contribute different nutrients across the day; each individual meal or snack does not need to include every food group. Choose varied meals through the day and include a dependable protein source and a dependable calcium source at more than one meal — curd, milk or paneer — rather than relying on trace amounts in mixed dishes or an optional extra. If you avoid dairy, include measured portions of calcium-fortified alternatives or calcium-set tofu, checking the label. Ragi and sesame can contribute, but should not be treated as equivalent replacements without checking quantities. Adults generally need about 1,000 mg of calcium a day, including while breastfeeding — a single measured serving is a helpful building block, not the whole day''s requirement on its own. Iron, vitamin B12, iodine and vitamin D are worth particular attention across a full week, especially if you''re breastfeeding or follow a restricted diet. Food choices alone don''t rule out a need for supplementation — ask your own clinician what''s right for you.',
   '[{"day_number": 1, "title": "Anchor", "notes": "A toddler who suddenly eats less, or only a narrow set of accepted foods, often means your own mealtime gets disrupted too — attention pulled toward their plate, your own food going cold, or skipped while you manage what''s happening across the table. This week is about protecting your own plate through that, whatever this phase looks like for your child.", "breakfast_a": "Besan chilla (2 pieces) with a tomato-onion salad and a small bowl of curd (150g)", "breakfast_b": "Boiled eggs (2) with whole-wheat toast (2 slices), cucumber and a small bowl of curd (150g)", "lunch_a": "Rice (1 cup cooked) with an urad-moong dal (3/4 cup) and a bhindi sabzi", "lunch_b": "Chicken curry (100g chicken) with rice (1 cup cooked) and a cauliflower sabzi", "nourishment_break_a": "Roasted chana (30g) with a pear and a small bowl of curd (150g)", "nourishment_break_b": "A glass of buttermilk (200ml) with roasted cumin", "dinner_a": "Roti (2 pieces) with a sabut moong dal (3/4 cup) and a green beans sabzi", "dinner_b": "Paneer curry (75g paneer) with roti (2 pieces) and a carrot-peas sabzi", "still_hungry": "A small bowl of curd (150g) with a few dates"}, {"day_number": 2, "title": "The plate that isn''t a negotiation", "notes": "Whatever pushback plays out on the other end of the table, your own meal doesn''t need their cooperation to count as finished.", "breakfast_a": "Vegetable idli (3 pieces) with sambar and a small bowl of curd (150g)", "breakfast_b": "Egg-and-capsicum toast (2 eggs, 2 slices) with a small bowl of curd (150g)", "lunch_a": "Rice (1 cup cooked) with a masoor dal (3/4 cup) and a tinda sabzi", "lunch_b": "Fish curry (100g fish) with rice (1 cup cooked) and a green beans sabzi", "nourishment_break_a": "Roasted makhana (30g) with an orange", "nourishment_break_b": "Fully cooked sprouted-moong salad (1 cup) with a squeeze of lemon", "dinner_a": "Roti (2 pieces) with a chana-methi curry (3/4 cup) and a small bowl of curd (150g)", "dinner_b": "Mutton curry (100g mutton) with roti (2 pieces), a cauliflower sabzi and a small bowl of curd (150g)", "still_hungry": "A banana"}, {"day_number": 3, "title": "When mealtimes turn into a battle", "notes": "A difficult mealtime standoff has a way of eating into your own meal too — cold, eaten standing at the counter, or skipped entirely while you manage the table. A calmer mealtime is worth working toward when you''re ready for it, but that''s a separate project from making sure you get to eat today.", "breakfast_a": "Curd rice (1 cup, with 150g curd) with pomegranate", "breakfast_b": "Moong dal cheela (2 pieces) with coriander chutney and a small bowl of curd (150g)", "lunch_a": "Rice (1 cup cooked) with a kabuli chana curry (3/4 cup) and a capsicum sabzi", "lunch_b": "Prawn curry (100g prawn) with rice (1 cup cooked) and a green beans sabzi", "nourishment_break_a": "A pear with roasted walnuts (15g) and a small bowl of curd (150g)", "nourishment_break_b": "Buttermilk (200ml) with roasted fennel seeds", "dinner_a": "Roti (2 pieces) with a lobia-tomato curry (3/4 cup)", "dinner_b": "Chicken-and-methi curry (100g chicken) with roti (2 pieces)", "still_hungry": "A glass of warm milk (200ml)"}, {"day_number": 4, "title": "If someone suggests cutting things from your own diet too", "notes": "A fussy toddler often invites advice — including suggestions to remove dairy, gluten or entire food groups from the family''s meals in the hope that it fixes the refusal. Without a clinical diagnosis behind it, that isn''t an established way to resolve ordinary picky eating, and it doesn''t need to reshape your own plate.", "breakfast_a": "Oats-vegetable uttapam (2 pieces) with sambar", "breakfast_b": "Egg bhurji (2 eggs) with whole-wheat toast (2 slices)", "lunch_a": "Rice (1 cup cooked) with a mild dal makhani (3/4 cup), a cauliflower sabzi and a small bowl of curd (150g)", "lunch_b": "Paneer curry (75g paneer) with rice (1 cup cooked) and a green beans sabzi", "nourishment_break_a": "Roasted peanuts (15g) with a guava and a small bowl of curd (150g)", "nourishment_break_b": "Curd (150g) with a spoon of roasted flaxseed", "dinner_a": "Roti (2 pieces) with a masoor-arhar dal (3/4 cup) and a bhindi sabzi", "dinner_b": "Chicken curry (100g chicken) with roti (2 pieces) and a capsicum sabzi", "still_hungry": "A small bowl of curd (150g)"}, {"day_number": 5, "title": "Family meals, imperfect and shared", "notes": "Eating together — even a simple, repeated meal, without screens, without pressure to finish — remains one of the more consistently useful habits during a picky phase. It doesn''t have to be elaborate, and it isn''t only for your toddler''s benefit: a shared table is also where your own meal gets protected.", "breakfast_a": "Ragi dosa (2 pieces) with coconut chutney, sambar and a small bowl of curd (150g)", "breakfast_b": "Egg-and-mushroom toast (2 eggs, 2 slices) with a small bowl of curd (150g)", "lunch_a": "Rice (1 cup cooked) with an arhar dal (3/4 cup) and a lauki sabzi", "lunch_b": "Mutton curry (100g mutton) with rice (1 cup cooked) and a green beans sabzi", "nourishment_break_a": "Roasted almonds (15g) with a banana and a small bowl of curd (150g)", "nourishment_break_b": "A glass of milk (200ml) with a few soaked raisins", "dinner_a": "Roti (2 pieces) with a chana-spinach curry (3/4 cup)", "dinner_b": "Fish curry (100g fish) with roti (2 pieces) and a cauliflower sabzi", "still_hungry": "A few plain crackers with curd (150g)"}, {"day_number": 6, "title": "If mealtime stress is affecting your own eating", "notes": "A consistently difficult mealtime, day after day, can quietly chip away at your own appetite too — a skipped breakfast, a smaller lunch, less patience for cooking anything beyond the bare minimum. That''s a common response to sustained stress, not a personal failing, but it''s worth noticing if it''s become the pattern more days than not. Worth knowing: If you notice you''re eating noticeably less than usual for more than a week or two, feeling persistently low on energy, or your own weight is shifting in a way that concerns you, it''s worth mentioning to your own doctor rather than waiting for the phase to pass. If you''re significantly unwell, or struggling to eat or drink at all, don''t wait — contact your doctor promptly instead.", "breakfast_a": "Sooji upma (1 cup cooked) with mixed vegetables and a small bowl of curd (150g)", "breakfast_b": "Egg-and-onion omelette (2 eggs) with whole-wheat toast (2 slices) and a small bowl of curd (150g)", "lunch_a": "Rice (1 cup cooked) with a moong-chana dal (3/4 cup) and a carrot-peas sabzi", "lunch_b": "Chicken-and-tomato curry (100g chicken) with rice (1 cup cooked) and a bhindi sabzi", "nourishment_break_a": "Buttermilk (200ml) with roasted chana", "nourishment_break_b": "A pear with roasted sesame seeds (1 tbsp)", "dinner_a": "Roti (2 pieces) with a rajma-spinach curry (3/4 cup) and a small bowl of curd (150g)", "dinner_b": "Paneer curry (75g paneer) with roti (2 pieces) and a lauki sabzi", "still_hungry": "A glass of warm milk (200ml) with a pinch of turmeric"}, {"day_number": 7, "title": "A repeat-favourites day", "notes": "No new recipes today. Day 1''s combination is repeated below as a ready option — or swap in whichever meals from earlier in the week worked best for you. No forced choices today. Is there a mealtime habit that''s crept in — skipping your own plate to manage theirs, or something else — and would it help to name it out loud rather than just push through it?", "breakfast_a": "Besan chilla (2 pieces) with a tomato-onion salad and a small bowl of curd (150g)", "breakfast_b": "Boiled eggs (2) with whole-wheat toast (2 slices), cucumber and a small bowl of curd (150g)", "lunch_a": "Rice (1 cup cooked) with an urad-moong dal (3/4 cup) and a bhindi sabzi", "lunch_b": "Chicken curry (100g chicken) with rice (1 cup cooked) and a cauliflower sabzi", "nourishment_break_a": "Roasted chana (30g) with a pear and a small bowl of curd (150g)", "nourishment_break_b": "A glass of buttermilk (200ml) with roasted cumin", "dinner_a": "Roti (2 pieces) with a sabut moong dal (3/4 cup) and a green beans sabzi", "dinner_b": "Paneer curry (75g paneer) with roti (2 pieces) and a carrot-peas sabzi", "still_hungry": "A small bowl of curd (150g) with a few dates"}]'::jsonb,
   'What would it look like to treat a hard mealtime as information about this phase, rather than as something urgent for you to fix by skipping your own plate?',
   'Next week continues Phase 5 with another piece of life beyond the first year — still grounded in the same idea: your own meals stay worth protecting, whatever else is unsettled around them.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- postpartum week 57: Eating well through a postpartum thyroid swing (CORRECTED — mother-centric rework)
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   57,
   NULL,
   'Phase 5 of 6 — Beyond the first year',
   'Eating well through a postpartum thyroid swing',
   '"Persistent fatigue, anxiety or unexplained weight change deserves a thyroid check — not just more willpower or a stricter diet."',
   'Postpartum thyroiditis usually begins during the first year after birth, but its underactive phase — and the symptoms associated with it — may continue beyond the first birthday. A new or persistent thyroid symptom at this stage still deserves medical assessment, but it should not automatically be assumed to be postpartum thyroiditis. Postpartum thyroiditis is an autoimmune inflammation of the thyroid that affects approximately 5-10% of women during the first year after birth, with risk being higher in women who have type 1 diabetes, thyroid antibodies, or a personal or family history of autoimmune thyroid disease. It may cause an overactive phase, an underactive phase, or both in sequence; symptoms can be mild or go unnoticed. An overactive phase, when it happens, tends to appear in the first few months after birth: a racing heart, anxiety, poor sleep, appetite or weight changes, and irritability. An underactive phase can follow it, or appear on its own, and can last the better part of a year: fatigue, weight gain, constipation, dry skin and low mood. Because these symptoms overlap with ordinary postpartum exhaustion, mood changes and stress, symptoms alone cannot confirm the cause. A clinician can assess the full picture and use thyroid blood tests — commonly including TSH and free T4 — to investigate it. Most people''s thyroid function settles back to normal within twelve to eighteen months of symptom onset, though a meaningful share go on to need longer-term thyroid hormone treatment. None of this reflects anything you did or didn''t do, and it isn''t something a diet, cleanse or supplement fixes on its own. Food''s role here is steady support — regular, adequate meals while this settles — not an attempt to self-treat symptoms through iodine-heavy foods, kelp, or thyroid "support" products.',
   'If you''ve been diagnosed with postpartum thyroiditis, hypothyroidism or hyperthyroidism: continue your doctor''s monitoring and any prescribed medication exactly — food supports you through this, but it doesn''t replace thyroid hormone treatment when that''s needed. If you have a pre-existing thyroid condition, such as Hashimoto''s or Graves'', or known thyroid antibodies: the postpartum period carries a meaningfully higher chance of a flare or shift — keep up with your usual follow-up rather than assuming things have stayed stable. If you''re trying to conceive again or newly pregnant while your thyroid is still settling: ask for a TSH check before or as soon as you conceive, since thyroid balance is assessed differently in a new pregnancy. If you also manage diabetes, PCOS, high blood pressure, kidney disease, anaemia, food allergies or another condition: use the meal choices and portions recommended for you by your healthcare team. This general weekly plan should not override an individual treatment plan, and — if diabetes is part of your plan — the A and B meal options here aren''t matched for exact carbohydrate content either. Thyroid symptoms can persist beyond the first postpartum year, and other thyroid conditions can also appear at this stage. Either way, they are medical concerns — not a reflection of how well you have eaten or cared for yourself.',
   'Meat, fish and eggs can all sit comfortably in a regular week''s meals here, rotated for variety. If you are pregnant or breastfeeding and eat fish, FDA/EPA guidance recommends two to three adult servings weekly from its "Best Choices" list — about 113 g per serving before cooking. Follow local advisories. This is an option for fish eaters, not a requirement to add fish.',
   'Choose either option, not both — these are alternatives, not two separate meals. Repeating a combination you already enjoyed earlier in the week is completely fine; you don''t need six different dishes to get through the week. If nothing here appeals or time is short, reheated dal, rice and curd is an option if it suits your dietary needs and any care plan you follow. The "if you''re still hungry" suggestions are suggestions, not limits — adjust everything to your own appetite. Portions below are adjustable starting points, not maximum allowances — scale to your own appetite, activity and any care plan you follow. A cup means a standard 240ml measuring cup. Unless a dish says otherwise: rice or another cooked grain eaten on its own is one level cup (about 150g); khichdi (grain and dal cooked together) is a heaped cup (about 250g total), of which dal makes up roughly a third; a dal, bean or lentil curry eaten as its own dish is three-quarters of a cup cooked (about 150g); a roti is one medium piece; an idli or cheela is 2-3 pieces, and toast is 2 slices. In a mixed rice or grain dish, the meat, fish, paneer or legume component is about 75-100g of that ingredient (roughly a palm-sized piece, or half a cup of cooked legumes), counted separately from the grain itself. Paneer, tofu, meat or fish eaten as a dish''s main item is 75-100g cooked (a palm-sized piece), or two eggs — these are different foods with different protein, iron and fat content, and are not nutritionally interchangeable just because they share a similar portion size. Curd or milk is a small bowl or glass (150-200ml); a cooked vegetable side is about a cup; nuts or seeds used as a topping are about a tablespoon (roughly 10-15g). The meals contribute different nutrients across the day; each individual meal or snack does not need to include every food group. Choose varied meals through the day and include a dependable protein source and a dependable calcium source at more than one meal — curd, milk or paneer — rather than relying on trace amounts in mixed dishes or an optional extra. If you avoid dairy, include measured portions of calcium-fortified alternatives or calcium-set tofu, checking the label. Ragi and sesame can contribute, but should not be treated as equivalent replacements without checking quantities. Adults generally need about 1,000 mg of calcium a day, including while breastfeeding — a single measured serving is a helpful building block, not the whole day''s requirement on its own. If you take levothyroxine or another thyroid medicine, remember that timing matters as much as quantity — see Day 4. Iron, vitamin B12, iodine and vitamin D are worth particular attention across a full week, especially if you follow a restricted diet. Food choices alone don''t rule out a need for supplementation — ask your own clinician what''s right for you.',
   '[{"day_number": 1, "title": "Anchor", "notes": "Postpartum thyroiditis usually begins within the first year after delivery, but its effects may continue beyond it. If you have recently entered your child''s second year and still feel unmistakably \"off,\" take that seriously rather than assuming it is ordinary tiredness.", "breakfast_a": "Moong dal dosa (2 pieces) with tomato chutney and a small bowl of curd (150g)", "breakfast_b": "Egg-and-carrot toast (2 eggs, 2 slices) with a glass of milk (200ml)", "lunch_a": "Rice (1 cup cooked) with a matki dal (3/4 cup) and a cabbage sabzi", "lunch_b": "Fish curry (100g fish) with rice (1 cup cooked) and a bhindi sabzi", "nourishment_break_a": "Roasted walnuts (15g) with a banana and a small bowl of curd (150g)", "nourishment_break_b": "A glass of buttermilk (200ml) with a small bowl of roasted chana (30g)", "dinner_a": "Roti (2 pieces) with a chana-lauki curry (3/4 cup)", "dinner_b": "Minced chicken (100g chicken) with peas and roti (2 pieces)", "still_hungry": "A boiled egg"}, {"day_number": 2, "title": "When it feels like restlessness, not recovery", "notes": "An overactive phase can follow birth in some women — a racing heart, anxiety, trouble sleeping, unexpected weight loss despite eating normally, or a new edge of irritability. It usually shows up in the first few months after delivery and is easy to mistake for ordinary new-parent stress. Worth knowing: These symptoms are commonly written off as stress or anxiety, but symptoms alone cannot identify the cause. A clinician can assess them and order thyroid blood tests when appropriate. If palpitations, unexplained weight loss or persistent anxiety are new and lasting, it''s worth mentioning to your doctor rather than assuming it will pass on its own. Seek urgent medical care for chest pain, fainting, severe breathlessness, confusion, or a very fast or irregular heartbeat that does not settle — these should not be managed through food changes alone.", "breakfast_a": "Vegetable-stuffed roti (2 pieces) with a small bowl of curd (150g)", "breakfast_b": "Boiled eggs (2) with one slice of whole-grain toast, a guava and a glass of milk (200ml)", "lunch_a": "Rice (1 cup cooked) with a toor dal (3/4 cup) and a capsicum sabzi", "lunch_b": "Paneer curry (75g paneer) with rice (1 cup cooked) and a cabbage sabzi", "nourishment_break_a": "Roasted chana (30g) with an orange and a small bowl of curd (150g)", "nourishment_break_b": "A banana with a glass of milk (200ml)", "dinner_a": "Roti (2 pieces) with a rajma-tomato curry (3/4 cup)", "dinner_b": "Mutton curry (100g mutton) with rice (1 cup cooked) and a bhindi sabzi", "still_hungry": "A small bowl of curd (150g)"}, {"day_number": 3, "title": "When it feels like exhaustion food alone can''t fix", "notes": "An underactive phase can follow the restless one, or turn up on its own — fatigue, weight gain, constipation, dry skin, low mood and poor exercise tolerance, often several months after birth, sometimes lasting the better part of a year. Worth knowing: This phase can look a lot like ordinary depletion. If the symptoms are persistent or affecting daily life, a clinician can assess whether thyroid dysfunction or another medical concern may be contributing. Persistent low mood alongside these physical symptoms is worth raising with your doctor — it isn''t something to push through with willpower or a stricter diet.", "breakfast_a": "Ragi porridge (1 cup, with milk, 200ml) with roasted walnuts (15g)", "breakfast_b": "Egg-and-spinach bhurji (2 eggs) with toast (2 slices) and a small bowl of curd (150g)", "lunch_a": "Rice (1 cup cooked) with a moong-lauki dal (3/4 cup) and a cooked vegetable", "lunch_b": "Chicken-and-spinach curry (100g chicken) with rice (1 cup cooked) and a cooked vegetable", "nourishment_break_a": "Curd (150g) with a spoon of roasted sesame seeds", "nourishment_break_b": "A pear with roasted peanuts (15g) and a glass of milk (200ml)", "dinner_a": "Roti (2 pieces) with a masoor dal (3/4 cup) and a cooked vegetable", "dinner_b": "Fish curry (100g fish) with roti (2 pieces) and a cooked vegetable", "still_hungry": "A glass of warm milk (200ml)"}, {"day_number": 4, "title": "If you''ve been prescribed thyroid medicine", "notes": "If you take levothyroxine, it is commonly taken with plain water on an empty stomach, usually 30-60 minutes before breakfast, or at bedtime several hours after the last meal. Calcium and iron supplements — and calcium-rich foods like the curd or milk in many of this week''s breakfasts — can reduce its absorption and are generally kept at least four hours apart. Follow the exact instructions given with your prescription, because your clinician may recommend a different routine; feel free to move a meal''s dairy component to a later eating occasion if that fits your instructions better. Worth knowing: If this applies to you (you take thyroid medicine): take your medicine at a consistent time, and tell your doctor or pharmacist about calcium, iron, antacids, multivitamins and other supplements. Do not change the dose or timing on your own. If you take a thyroid medicine other than levothyroxine, follow the instructions specific to that medicine.", "breakfast_a": "Oats idli (3 pieces) with sambar and a small bowl of curd (150g)", "breakfast_b": "Egg-and-tomato bhurji (2 eggs) with toast (2 slices) and a glass of milk (200ml)", "lunch_a": "Rice (1 cup cooked) with a chana dal (3/4 cup) and a capsicum sabzi", "lunch_b": "Paneer curry (75g paneer) with rice (1 cup cooked) and a bhindi sabzi", "nourishment_break_a": "Curd (150g) with a spoon of soaked sabja seeds", "nourishment_break_b": "Roasted makhana (15g) with a pear and a glass of milk (200ml)", "dinner_a": "Roti (2 pieces) with an urad dal (3/4 cup) and a cooked vegetable", "dinner_b": "Chicken curry (100g chicken) with roti (2 pieces) and a cooked vegetable", "still_hungry": "A few plain crackers with curd (150g)"}, {"day_number": 5, "title": "If someone suggests iodine or a thyroid \"support\" product", "notes": "More iodine is not automatically better. Kelp tablets, iodine drops, seaweed concentrates and some \"thyroid support\" blends can provide very large or unpredictable amounts and may worsen thyroid dysfunction in susceptible people. Continue using ordinary foods and iodized salt in normal dietary amounts unless your clinician advises differently, but do not begin a concentrated iodine or kelp product to treat thyroid symptoms yourself.", "breakfast_a": "Idli (3 pieces) with coconut chutney, sambar and a small bowl of curd (150g)", "breakfast_b": "Egg-and-onion toast (2 eggs, 2 slices) with a glass of milk (200ml)", "lunch_a": "Rice (1 cup cooked) with a rajma dal (3/4 cup) and a cauliflower sabzi", "lunch_b": "Fish (100g fish) with lemon rice (1 cup cooked) and beans", "nourishment_break_a": "A guava with roasted chana (30g) and a small bowl of curd (150g)", "nourishment_break_b": "A banana with plain curd (150g) and a spoon of ground sesame seeds", "dinner_a": "Roti (2 pieces) with a green-gram dal (3/4 cup) and a cooked vegetable", "dinner_b": "Chicken curry (100g chicken) with rice (1 cup cooked) and a cooked vegetable", "still_hungry": "A banana"}, {"day_number": 6, "title": "If you''re thinking about another pregnancy while this settles", "notes": "Thyroid balance matters differently once you''re pregnant again, and having had postpartum thyroiditis once makes it considerably more likely to happen again after a future birth. Worth knowing: If this applies to you (you''re trying to conceive again or newly pregnant and your thyroid function hasn''t been rechecked since birth): ask for a TSH check before or as soon as you conceive, especially if you had any thyroid symptoms or a diagnosis after this birth.", "breakfast_a": "Besan cheela (2 pieces) with tomato chutney and a small bowl of curd (150g)", "breakfast_b": "Egg-and-capsicum bhurji (2 eggs) with toast (2 slices) and a glass of milk (200ml)", "lunch_a": "Rice (1 cup cooked) with a moong dal (3/4 cup) and a cauliflower sabzi", "lunch_b": "Chicken-and-moong khichdi (1 heaped cup, 100g chicken)", "nourishment_break_a": "Roasted almonds (15g) with a guava and a small bowl of curd (150g)", "nourishment_break_b": "A glass of milk (200ml) with a date or two and a small handful of roasted chana (15g)", "dinner_a": "Roti (2 pieces) with a rajma curry (3/4 cup) and a cooked vegetable", "dinner_b": "Paneer curry (75g paneer) with roti (2 pieces) and a cooked vegetable", "still_hungry": "A small bowl of curd (150g) with a few dates"}, {"day_number": 7, "title": "A repeat-favourites day", "notes": "No new recipes today. Day 1''s combination is repeated below as a ready option — or swap in whichever meals from earlier in the week worked best for you. No forced choices today. Have you noticed any of this week''s symptoms in yourself since giving birth, and if so, is there a conversation with your doctor you''ve been putting off?", "breakfast_a": "Moong dal dosa (2 pieces) with tomato chutney and a small bowl of curd (150g)", "breakfast_b": "Egg-and-carrot toast (2 eggs, 2 slices) with a glass of milk (200ml)", "lunch_a": "Rice (1 cup cooked) with a matki dal (3/4 cup) and a cabbage sabzi", "lunch_b": "Chicken curry (100g chicken) with rice (1 cup cooked) and a bhindi sabzi", "nourishment_break_a": "Roasted walnuts (15g) with a banana and a small bowl of curd (150g)", "nourishment_break_b": "A glass of buttermilk (200ml) with a small bowl of roasted chana (30g)", "dinner_a": "Roti (2 pieces) with a chana-lauki curry (3/4 cup)", "dinner_b": "Minced chicken (100g chicken) with peas and roti (2 pieces)", "still_hungry": "A boiled egg"}]'::jsonb,
   'What would it look like to treat a stretch of unexplained fatigue or mood change as a medical question worth asking, rather than a personal failing to manage alone?',
   'Next week continues Phase 5 with another piece of life beyond the first year — still grounded in the same idea: your body''s signals are worth listening to, long after the earliest postpartum weeks have passed.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- postpartum week 59: Eating well during festivals and celebrations (CORRECTED — mother-centric rework)
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   59,
   NULL,
   'Phase 5 of 6 — Beyond the first year',
   'Eating well during festivals and celebrations',
   '"A festival plate can include the foods you love without turning into a diet you owe afterward."',
   'Festivals and celebrations bring food into a different register — abundance, tradition, generosity — and it''s common to treat that abundance as something to survive rather than enjoy, either by overeating past comfort or by white-knuckling restriction through every gathering. Enjoying festive food doesn''t require a plan to make up for it afterward. A day or two of richer, sweeter, more indulgent eating doesn''t undo months of regular meals, and it doesn''t need a stricter day to follow it. For anyone managing diabetes or another blood-sugar condition, festivals are also a common flashpoint — not because celebration itself is risky, but because meal timing, portion size and monitoring often slip on a busy, social day. A little extra planning protects you without requiring you to sit out the celebration. None of this is about permission or restriction. It''s about letting a festival be what it is — a full, human occasion — without treating your body as the thing that has to pay for it.',
   'If you manage diabetes or another blood-sugar condition: do not skip earlier meals to "save room" for festival food. Keep meals, medication and monitoring as close to your usual plan as reasonably possible, carry your usual treatment for low blood sugar, and use the monitoring schedule already recommended for you. If the celebration will substantially delay a meal, follow the adjustment plan given by your diabetes team rather than changing medication on your own. If you have a history of disordered eating or a difficult relationship with food: festive gatherings can genuinely be harder. It is reasonable to sit with a trusted person, prepare a neutral response to comments about food or bodies, step away from an uncomfortable conversation, or follow an existing support plan. You do not have to rely on willpower or manage the gathering alone. If you''re pregnant or breastfeeding: the usual caffeine and alcohol guidance still applies at a celebration, even when everyone around you is drinking or the day feels like an exception. A festival is one day, or a few, inside a much longer pattern of regular eating — it doesn''t need to be perfect, and it doesn''t need to be punished afterward either.',
   'Meat, fish and eggs can all sit comfortably in a regular week''s meals here, rotated for variety. If you are pregnant or breastfeeding and eat fish, FDA/EPA guidance recommends two to three adult servings weekly from its "Best Choices" list — about 113 g per serving before cooking. Follow local advisories. This is an option for fish eaters, not a requirement to add fish.',
   'Choose either option, not both — these are alternatives, not two separate meals. Repeating a combination you already enjoyed is completely fine; you don''t need a new dish every day. If nothing here appeals or time is short, reheated dal, rice and curd is an option if it suits your dietary needs and any care plan you follow. Portions below are adjustable starting points, not maximum allowances — scale to your own appetite, activity and any care plan you follow. A cup means a standard 240ml measuring cup. Unless a dish says otherwise: rice or another cooked grain eaten on its own is one level cup (about 150g); a dal, bean or lentil curry eaten as its own dish is three-quarters of a cup cooked (about 150g); a roti or paratha is one medium piece; an idli is 2-3 pieces, a chilla is 1-2 pieces, and toast is 2 slices. In a mixed rice or grain dish, the meat, fish, paneer or legume component is about 75-100g of that ingredient (roughly a palm-sized piece, or half a cup of cooked legumes), counted separately from the grain itself. Paneer, tofu, meat or fish eaten as a dish''s main item is 75-100g cooked (a palm-sized piece), or two eggs — these are different foods with different protein, iron and fat content, and are not nutritionally interchangeable just because they share a similar portion size. Curd or milk is a small bowl or glass (150-200ml); a cooked vegetable side is about a cup; nuts or seeds used as a topping are about a tablespoon (roughly 10g). The meals contribute different nutrients across the day; each individual meal or snack does not need to include every food group. Choose varied meals through the day and include a dependable protein source and a dependable calcium source at more than one meal — curd, milk or paneer — rather than relying on trace amounts in mixed dishes or an optional extra. If you avoid dairy, include measured portions of calcium-fortified alternatives or calcium-set tofu, checking the label. Ragi and sesame can contribute, but should not be treated as equivalent replacements without checking quantities. Adults generally need about 1,000 mg of calcium a day, including while breastfeeding — a single measured serving is a helpful building block, not the whole day''s requirement on its own. Iron, vitamin B12, iodine and vitamin D are worth particular attention across a full week, especially if you''re breastfeeding or follow a restricted diet. Food choices alone don''t rule out a need for supplementation — ask your own clinician what''s right for you.',
   '[{"day_number": 1, "title": "Anchor", "notes": "Festivals and celebrations bring food into a different register — abundance, tradition, generosity — and it''s common to treat that abundance as something to survive rather than enjoy, either by overeating past comfort or by white-knuckling restriction through every gathering. At the celebration: Choose the festive dishes that are meaningful to you. You can eat them alongside the rest of the meal, return for more if you are still hungry, or stop when you have had enough. There is no requirement to earn the food beforehand or correct for it afterward. Celebration choice: A favourite family sweet or savoury festival dish.", "breakfast_a": "Vegetable paratha (1 medium) with a bowl of curd (150g)", "breakfast_b": "Egg-and-mushroom omelette (2 eggs) with toast (2 slices) and a small bowl of curd (150g)", "lunch_a": "Rice (1 cup cooked) with a toor dal (3/4 cup) and a cabbage sabzi", "lunch_b": "Chicken curry (100g chicken) with rice (1 cup cooked) and a cabbage sabzi", "nourishment_break_a": "Roasted almonds (15g) with an orange and a small bowl of curd (150g)", "nourishment_break_b": "A glass of buttermilk (200ml) with roasted cumin and a small bowl of roasted chana (30g)", "dinner_a": "Roti (2 pieces) with a chana dal (3/4 cup) and a cabbage sabzi", "dinner_b": "Paneer-peas curry (75g paneer) with roti (2 pieces)", "still_hungry": "A banana"}, {"day_number": 2, "title": "If diabetes or blood sugar swings are part of your festival", "notes": "Festivals are a common flashpoint for anyone managing diabetes or another blood-sugar condition — not because celebrating is risky, but because meal timing, portion size and monitoring often slip on a busy, social day. Worth knowing: Regular, reasonably spaced meals can make a festival day more predictable. Enjoy sweets as part of a meal or alongside foods containing protein or fibre if that suits your established diabetes plan — pairing them this way doesn''t mean portion size stops mattering, so keep to the quantities your plan allows. Stay hydrated, monitor according to your usual instructions, and continue movement that is normal and safe for you. None of this means sitting out the foods that make the occasion meaningful. Celebration choice: If managing blood sugar, include the festive food in the meal pattern that normally works for you.", "breakfast_a": "Moong dal chilla (2 pieces) with mint chutney and a small bowl of curd (150g)", "breakfast_b": "Egg bhurji (2 eggs) with toast (2 slices) and a small bowl of curd (150g)", "lunch_a": "Rice (1 cup cooked) with a masoor dal (3/4 cup) and a capsicum sabzi", "lunch_b": "Fish curry (100g fish) with rice (1 cup cooked) and a capsicum sabzi", "nourishment_break_a": "Roasted chana (30g) with a guava and a small bowl of curd (150g)", "nourishment_break_b": "Buttermilk (200ml) with roasted ajwain and a banana", "dinner_a": "Roti (2 pieces) with a lauki-chana curry (3/4 cup)", "dinner_b": "Chicken kofta curry (100g chicken) with rice (1 cup cooked) and beans", "still_hungry": "A small bowl of curd (150g)"}, {"day_number": 3, "title": "When sweets are pressed on you", "notes": "\"Just one more,\" \"you''ve barely eaten anything\" — festive hospitality often comes with pressure to keep taking second and third helpings. A full plate of festival food is already a full plate. Declining more isn''t a rejection of the person offering, and you don''t owe anyone proof of how much you enjoyed the day. Celebration choice: Accept the amount you genuinely want; declining another serving does not reject the person offering it.", "breakfast_a": "Idli (3 pieces) with sambar, tomato chutney and a small bowl of curd (150g)", "breakfast_b": "Egg-and-capsicum omelette (2 eggs) with toast (2 slices) and a small bowl of curd (150g)", "lunch_a": "Rice (1 cup cooked) with a rajma dal (3/4 cup) and a cooked vegetable", "lunch_b": "Prawn curry (100g prawn) with rice (1 cup cooked) and a cooked vegetable", "nourishment_break_a": "A pear with roasted walnuts (15g) and a small bowl of curd (150g)", "nourishment_break_b": "Curd (150g) with a spoon of roasted flaxseed", "dinner_a": "Roti (2 pieces) with a moong-methi dal (3/4 cup) and a cooked vegetable", "dinner_b": "Mutton-and-spinach curry (100g mutton) with roti (2 pieces)", "still_hungry": "A small bowl of curd (150g)"}, {"day_number": 4, "title": "The morning after", "notes": "The day after a celebration is just an ordinary day again. It doesn''t need a stricter menu, a skipped meal, or a \"detox\" to make up for what you ate — regular, adequate meals pick back up where they left off, without punishment attached.", "breakfast_a": "Vegetable upma (1 cup cooked) with roasted peanuts (15g)", "breakfast_b": "Boiled eggs (2) with whole-grain toast (2 slices) and a banana", "lunch_a": "Rice (1 cup cooked) with a toor-masoor dal (3/4 cup), a cooked vegetable and a small bowl of curd (150g)", "lunch_b": "Paneer-and-tomato curry (75g paneer) with roti (2 pieces)", "nourishment_break_a": "A guava with roasted peanuts (15g) and a small bowl of curd (150g)", "nourishment_break_b": "A glass of milk (200ml) with soft fruit", "dinner_a": "Roti (2 pieces) with a rajma-spinach curry (3/4 cup)", "dinner_b": "Egg curry (2 eggs) with rice (1 cup cooked) and a cooked vegetable", "still_hungry": "A boiled egg, or a small bowl of roasted chana (30g) or curd (150g) if you''d rather keep it vegetarian"}, {"day_number": 5, "title": "If comments about your body come up", "notes": "Festivals often bring relatives and old acquaintances together, and with them, comments about your weight, your face, or how you look \"these days\" — sometimes meant kindly, sometimes not. None of that is a referendum on how you''re eating or taking care of yourself, and you don''t owe anyone a response beyond what you''re comfortable giving. A short, neutral reply — or simply changing the subject — works as well as any real answer, and it''s fine to walk toward the food table rather than stand around fielding more of it.", "breakfast_a": "Besan chilla (2 pieces) with a cucumber salad and a small bowl of curd (150g)", "breakfast_b": "Egg-and-mushroom bhurji (2 eggs) with toast (2 slices) and a small bowl of curd (150g)", "lunch_a": "Rice (1 cup cooked) with a chana-tomato dal (3/4 cup) and a cooked vegetable", "lunch_b": "Chicken-and-tomato curry (100g chicken) with roti (2 pieces) and a cooked vegetable", "nourishment_break_a": "A banana with plain curd (150g) and roasted makhana (15g)", "nourishment_break_b": "A glass of milk (200ml) with smooth cashew paste (1 tbsp) spread thinly on soft toast (2 slices)", "dinner_a": "Roti (2 pieces) with a green-moong dal (3/4 cup) and a cooked vegetable", "dinner_b": "Paneer-and-capsicum curry (75g paneer) with roti (2 pieces)", "still_hungry": "A small bowl of curd (150g)"}, {"day_number": 6, "title": "If alcohol is part of your celebration", "notes": "Weddings, New Year''s, a festival night out — celebrations often come with alcohol on the table, and it''s easy to feel like the exception should apply to you too. If this applies to you (alcohol is part of your celebration and you''re breastfeeding or could be pregnant): if you''re breastfeeding and choose to drink, allow at least two hours per standard drink before feeding, and make sure a sober adult is on hand. If you''re pregnant or could be, no amount of alcohol is known to be safe — an alcohol-free 0.0% drink for the toast can still make the occasion feel celebratory. If your child needs to feed before that waiting period has passed, previously expressed milk can be used if available. Pumping and discarding milk does not make alcohol leave the milk faster; alcohol levels fall as they fall in the bloodstream.", "breakfast_a": "Oats upma (1 cup cooked) with mixed vegetables and a small bowl of curd (150g)", "breakfast_b": "Boiled eggs (2) with whole-grain toast (2 slices), a guava and a small bowl of curd (150g)", "lunch_a": "Rice (1 cup cooked) with a chana-spinach dal (3/4 cup) and a cooked vegetable", "lunch_b": "Chicken-and-capsicum curry (100g chicken) with rice (1 cup cooked) and a cooked vegetable", "nourishment_break_a": "A mandarin with roasted peanuts (15g) and a small bowl of curd (150g)", "nourishment_break_b": "Curd (150g) with a spoon of roasted pumpkin seeds", "dinner_a": "Roti (2 pieces) with a masoor-chana dal (3/4 cup) and a cooked vegetable", "dinner_b": "Fish tikka (100g fish) with roti (2 pieces) and a cooked vegetable", "still_hungry": "A glass of warm milk (200ml)"}, {"day_number": 7, "title": "A repeat-favourites day", "notes": "No new recipes today. Day 1''s combination is repeated below as a ready option — or swap in whichever meals from earlier in the week worked best for you. No forced choices today. Is there a festival or celebration coming up where you could try letting yourself simply enjoy the food, without a plan to earn it beforehand or make up for it after?", "breakfast_a": "Vegetable paratha (1 medium) with a bowl of curd (150g)", "breakfast_b": "Egg-and-mushroom omelette (2 eggs) with toast (2 slices) and a small bowl of curd (150g)", "lunch_a": "Rice (1 cup cooked) with a toor dal (3/4 cup) and a cabbage sabzi", "lunch_b": "Chicken curry (100g chicken) with rice (1 cup cooked) and a cabbage sabzi", "nourishment_break_a": "Roasted almonds (15g) with an orange and a small bowl of curd (150g)", "nourishment_break_b": "A glass of buttermilk (200ml) with roasted cumin and a small bowl of roasted chana (30g)", "dinner_a": "Roti (2 pieces) with a chana dal (3/4 cup) and a cabbage sabzi", "dinner_b": "Paneer-peas curry (75g paneer) with roti (2 pieces)", "still_hungry": "A banana"}]'::jsonb,
   'What would it look like to let a celebration be fully enjoyable, without treating your next meal as a correction for it?',
   'Next week continues Phase 5 with another piece of life beyond the first year — still grounded in the same idea: an occasion worth celebrating is not one that needs to be paid for afterward.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- postpartum week 60: Eating well when your child is sick (CORRECTED — mother-centric rework)
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   60,
   NULL,
   'Phase 5 of 6 — Beyond the first year',
   'Eating well when your child is sick',
   '"Your child''s appetite is allowed to shrink today — yours still needs feeding, especially today."',
   'A sick child changes the shape of a day fast — a fever spikes, appetite disappears, sleep gets thin, and everyone''s plans narrow down to getting through the next few hours. It''s common for your own meals to be the first thing that quietly stops happening. A child''s appetite naturally drops during illness, and that''s usually not a sign of anything going wrong on its own — it tends to return as they recover. What''s easy to miss is that the same days often quietly cost you your own appetite and your own proper meals too. You deserve food and support during this stretch too. A day spent holding a feverish child, tracking symptoms and managing a smaller appetite than usual is still a full day of your own energy being spent — and it deserves real food, even in small, simple pieces. The daily meal choices below remain your own meals, not a recovery diet for your child — your child''s illness doesn''t mean your own plate should shrink or restrict itself to match.',
   'If you are also unwell while caring for a sick child: your own hydration, food and rest still matter, and it''s reasonable to ask someone else to take a shift so you can eat a proper meal or sleep. If you manage diabetes or another condition affected by irregular eating: a day of smaller or delayed meals while caregiving can still affect you — keep your usual monitoring and treatment plan close at hand even when the day doesn''t go as planned. Feeding a sick child well and feeding yourself well are not competing tasks this week — they''re both part of getting the household through to the other side of this illness.',
   'Meat, fish and eggs can all sit comfortably in a regular week''s meals here, rotated for variety. If you are pregnant or breastfeeding and eat fish, FDA/EPA guidance recommends two to three adult servings weekly from its "Best Choices" list — about 113 g per serving before cooking. Follow local advisories. This is an option for fish eaters, not a requirement to add fish.',
   'Choose either option, not both — these are alternatives, not two separate meals. Repeating a combination you already enjoyed is completely fine; you don''t need a new dish every day. If nothing here appeals or time is short, reheated dal, rice and curd is an option if it suits your dietary needs and any care plan you follow. Portions below are adjustable starting points, not maximum allowances — scale to your own appetite, activity and any care plan you follow. A cup means a standard 240ml measuring cup. Unless a dish says otherwise: rice or another cooked grain eaten on its own is one level cup (about 150g); khichdi (grain and dal cooked together) is a heaped cup (about 250g total), of which dal makes up roughly a third; a dal, bean or lentil curry eaten as its own dish is three-quarters of a cup cooked (about 150g); a roti or paratha is one medium piece; an idli is 2-3 pieces, a cheela or chilla is 1-2 pieces, and toast is 2 slices. In a mixed rice or grain dish, the meat, fish, paneer or legume component is about 75-100g of that ingredient (roughly a palm-sized piece, or half a cup of cooked legumes), counted separately from the grain itself. Paneer, tofu, meat or fish eaten as a dish''s main item is 75-100g cooked (a palm-sized piece), or two eggs — these are different foods with different protein, iron and fat content, and are not nutritionally interchangeable just because they share a similar portion size. Curd or milk is a small bowl or glass (150-200ml); a cooked vegetable side is about a cup; nuts or seeds used as a topping are about a tablespoon (roughly 10g). The meals contribute different nutrients across the day; each individual meal or snack does not need to include every food group. Choose varied meals through the day and include a dependable protein source and a dependable calcium source at more than one meal — curd, milk or paneer — rather than relying on trace amounts in mixed dishes or an optional extra. If you avoid dairy, include measured portions of calcium-fortified alternatives or calcium-set tofu, checking the label. Ragi and sesame can contribute, but should not be treated as equivalent replacements without checking quantities. Adults generally need about 1,000 mg of calcium a day, including while breastfeeding — a single measured serving is a helpful building block, not the whole day''s requirement on its own. Iron, vitamin B12, iodine and vitamin D are worth particular attention across a full week, especially if you''re breastfeeding or follow a restricted diet. Food choices alone don''t rule out a need for supplementation — ask your own clinician what''s right for you.',
   '[{"day_number": 1, "title": "Anchor", "notes": "A sick day rarely goes as planned. Meals get skipped, plans get dropped, and everyone in the house ends up running on whatever''s easiest to grab. This week is about keeping a little structure for your own eating even while your child''s routine is upside down.", "breakfast_a": "Vegetable dalia (1 cup cooked) with roasted peanuts (15g) and a small bowl of curd (150g)", "breakfast_b": "Egg-and-tomato omelette (2 eggs) with toast (2 slices) and a small bowl of curd (150g)", "lunch_a": "Rice (1 cup cooked) with a moong dal (3/4 cup) and a carrot sabzi", "lunch_b": "Chicken curry (100g chicken) with rice (1 cup cooked) and a carrot sabzi", "nourishment_break_a": "Roasted peanuts (15g) with a mandarin and a small bowl of curd (150g)", "nourishment_break_b": "Buttermilk (200ml) with roasted cumin and a small bowl of roasted chana (30g)", "dinner_a": "Roti (2 pieces) with a chana dal (3/4 cup) and a carrot sabzi", "dinner_b": "Paneer-peas curry (75g paneer) with roti (2 pieces)", "still_hungry": "A banana"}, {"day_number": 2, "title": "When your child won''t eat", "notes": "A reduced appetite during your child''s illness often coincides with your own meals quietly falling away too — it''s easy to feel like there''s little point cooking properly when no one else at the table is eating much. Your appetite may change under stress, but your own nourishment still matters.", "breakfast_a": "Plain idli (3 pieces) with sambar", "breakfast_b": "Egg-and-carrot bhurji (2 eggs) with toast (2 slices)", "lunch_a": "Rice (1 cup cooked) with a masoor dal (3/4 cup) and a cooked vegetable", "lunch_b": "Chicken curry (100g chicken) with roti (2 pieces) and a cooked vegetable", "nourishment_break_a": "A pear with roasted chana (30g) and a small bowl of curd (150g)", "nourishment_break_b": "Curd (150g) with a spoon of soaked sabja seeds", "dinner_a": "Roti (2 pieces) with a toor-moong dal (3/4 cup), a cooked vegetable and a small bowl of curd (150g)", "dinner_b": "Paneer-and-spinach curry (75g paneer) with roti (2 pieces)", "still_hungry": "A small bowl of curd (150g)"}, {"day_number": 3, "title": "Your own plate doesn''t need to shrink to match theirs", "notes": "It''s common for a whole household''s meals to simplify to whatever a sick child can manage — plain toast, khichdi, curd rice — while everyone else''s plates quietly shrink and blandify right along with it. There''s no reason your own meal needs to follow that same restricted, bland pattern just because the kitchen has gone quiet this week.", "breakfast_a": "Vegetable poha (1 cup cooked) with roasted chana (30g), a squeeze of lemon and a small bowl of curd (150g)", "breakfast_b": "Egg-and-tomato bhurji (2 eggs) with toast (2 slices) and a small bowl of curd (150g)", "lunch_a": "Rice (1 cup cooked) with a toor dal (3/4 cup) and a cooked vegetable", "lunch_b": "Fish-and-tomato curry (100g fish) with rice (1 cup cooked) and a cooked vegetable", "nourishment_break_a": "A pear with plain curd (150g)", "nourishment_break_b": "A glass of milk (200ml) with a banana", "dinner_a": "Roti (2 pieces) with a rajma-lauki curry (3/4 cup)", "dinner_b": "Mutton-and-tomato curry (100g mutton) with roti (2 pieces)", "still_hungry": "A boiled egg"}, {"day_number": 4, "title": "If you''re too worried to think about your own meal", "notes": "A day when you''re genuinely worried about your child can make everything else, including your own plate, feel beside the point. If something about your child''s condition concerns you, contact your pediatrician promptly — that always comes first. But whatever the day holds medically, you still need to eat something yourself to keep functioning through it. For you: Whatever care or fluids your child needs today isn''t a substitute for your own meals. Even on a day this stressful, continue eating simple, complete food yourself, even in small amounts.", "breakfast_a": "Vegetable upma (1 cup cooked) with curd (150g)", "breakfast_b": "Fully cooked eggs (2) with toast (2 slices) and a banana", "lunch_a": "Rice (1 cup cooked) with moong dal (3/4 cup) and a soft cooked vegetable", "lunch_b": "Chicken-and-vegetable soup (100g chicken) with rice (1 cup cooked)", "nourishment_break_a": "A banana with plain curd (150g)", "nourishment_break_b": "Roasted chana (30g) with a glass of buttermilk (200ml)", "dinner_a": "Soft vegetable khichdi (1 heaped cup, dal about a third of that) with curd (150g)", "dinner_b": "Paneer bhurji (75g paneer) with rice (1 cup cooked) and a cooked vegetable", "still_hungry": "Warm milk (200ml) or toast (2 slices) with curd (150g)"}, {"day_number": 5, "title": "Feeding yourself while you''re the one holding it", "notes": "Caring for a sick child is its own kind of full-time work — checking a temperature, offering sips, sitting through a nap that only happens on you. It''s easy for your own last proper meal to have been many hours ago without you quite noticing. Worth knowing: Keep a few foods on hand that need no real preparation — a piece of fruit, boiled eggs made in advance and kept refrigerated, curd, or roasted nuts. Tea can accompany one of these, but doesn''t replace it. Eating something simple now is more useful to you than waiting for a chance to cook the ideal meal.", "breakfast_a": "Moong dal cheela (2 pieces) with tomato chutney", "breakfast_b": "Egg-and-capsicum bhurji (2 eggs) with toast (2 slices)", "lunch_a": "Rice (1 cup cooked) with a chana-methi curry (3/4 cup) and a small bowl of curd (150g)", "lunch_b": "Paneer-and-methi curry (75g paneer) with rice (1 cup cooked)", "nourishment_break_a": "A mandarin with roasted chana (30g) and a small bowl of curd (150g)", "nourishment_break_b": "A glass of milk (200ml) with smooth walnut paste (1 tbsp) spread thinly on soft toast (2 slices)", "dinner_a": "Roti (2 pieces) with a masoor dal (3/4 cup) and a cooked vegetable", "dinner_b": "Chicken-and-lauki curry (100g chicken) with roti (2 pieces)", "still_hungry": "A small bowl of curd (150g)"}, {"day_number": 6, "title": "When the rest of the household needs to step up", "notes": "One person cannot be the only one tracking medicine doses, cooking, comforting a child and eating regular meals for days in a row. If there''s a partner, family member or friend who can take over even one meal or one stretch of childcare, this is a reasonable week to ask.", "breakfast_a": "Besan chilla (2 pieces) with a grated carrot filling and a small bowl of curd (150g)", "breakfast_b": "Boiled eggs (2) with whole-grain toast (2 slices), a pear and a small bowl of curd (150g)", "lunch_a": "Rice (1 cup cooked) with a masoor-matki dal (3/4 cup) and a cooked vegetable", "lunch_b": "Chicken-and-spinach curry (100g chicken) with rice (1 cup cooked) and a cooked vegetable", "nourishment_break_a": "An orange with roasted chana (30g) and a small bowl of curd (150g)", "nourishment_break_b": "Curd (150g) with finely ground melon seeds", "dinner_a": "Roti (2 pieces) with a lobia-tomato curry (3/4 cup)", "dinner_b": "Fish curry (100g fish) with roti (2 pieces) and a cooked vegetable", "still_hungry": "A glass of warm milk (200ml)"}, {"day_number": 7, "title": "A repeat-favourites day", "notes": "No new recipes today. Day 1''s combination is repeated below as a ready option — or swap in whichever meals from earlier in the week worked best for you. No forced choices today. During the last stretch of illness in your house, was there a moment when feeding yourself became especially difficult? What food, preparation or practical support might make that moment easier next time?", "breakfast_a": "Vegetable dalia (1 cup cooked) with roasted peanuts (15g) and a small bowl of curd (150g)", "breakfast_b": "Egg-and-tomato omelette (2 eggs) with toast (2 slices) and a small bowl of curd (150g)", "lunch_a": "Rice (1 cup cooked) with a moong dal (3/4 cup) and a carrot sabzi", "lunch_b": "Chicken curry (100g chicken) with rice (1 cup cooked) and a carrot sabzi", "nourishment_break_a": "Roasted peanuts (15g) with a mandarin and a small bowl of curd (150g)", "nourishment_break_b": "Buttermilk (200ml) with roasted cumin and a small bowl of roasted chana (30g)", "dinner_a": "Roti (2 pieces) with a chana dal (3/4 cup) and a carrot sabzi", "dinner_b": "Paneer-peas curry (75g paneer) with roti (2 pieces)", "still_hungry": "A banana"}]'::jsonb,
   'What would it look like to treat your own meals as part of caring for a sick child, not something that waits until they''re better?',
   'Next week continues Phase 5 with another piece of life beyond the first year — still grounded in the same idea: caring for your child well includes caring for yourself while you do it.')
